#!/usr/bin/env node

/**
 * Comedy Houston — Weekly roundup auto-poster.
 *
 * Posts the Monday weekly roundup (6-tile hero + AI caption, generated by
 * generate-blog-post.js earlier in the same workflow and pushed to main) to:
 *
 *   1. Instagram Feed — hero square + caption  (anchor: failure = exit 1)
 *   2. Facebook Feed  — hero square + caption  (best-effort)
 *
 * No story variants — the weekly hero is a 1080×1080 asset, and the daily
 * "Tonight in Houston" posts already keep stories warm seven days a week.
 *
 * Freshness contract: blog/weekly-meta.json is only written by
 * generate-blog-post.js AFTER this week's caption + hero both exist. If
 * meta.week_monday doesn't match the current Houston week, generation
 * failed upstream and we skip rather than repost last week's creative.
 * weekly-post-state.json records the last posted week so the Thursday run
 * of the same workflow (weekend-post refresh) and manual re-runs can't
 * double-post. State only advances after the anchor channel succeeds.
 */

const fs = require("fs");
const path = require("path");

const {
  withTimeout,
  waitForImageUrl,
  resolveFacebookPageId,
  validateTokenAndGuards,
  postIgFeedImage,
  postFbFeedPhoto,
  shutdown,
} = require("./lib/meta-api");

const ROOT = path.resolve(__dirname, "..");
const BLOG_DIR = path.join(ROOT, "blog");
const META_PATH = path.join(BLOG_DIR, "weekly-meta.json");
const STATE_PATH = path.join(BLOG_DIR, "weekly-post-state.json");

const CHANNEL_TIMEOUT_MS = parseInt(process.env.IG_CHANNEL_TIMEOUT_MS || "180000", 10);

// Monday (YYYY-MM-DD) of the current week in Houston. Must agree with
// getCurrentWeekRange() in generate-blog-post.js, which runs under
// TZ=America/Chicago in the workflow.
function currentWeekMonday() {
  const todayStr = new Intl.DateTimeFormat("en-CA", {
    timeZone: "America/Chicago",
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
  }).format(new Date());
  const d = new Date(todayStr + "T12:00:00Z");
  d.setUTCDate(d.getUTCDate() - ((d.getUTCDay() + 6) % 7));
  return d.toISOString().slice(0, 10);
}

async function main() {
  console.log("=== Comedy Houston — Weekly Roundup Poster ===");
  console.log(`    Time: ${new Date().toISOString()}\n`);

  const weekMonday = currentWeekMonday();

  // --- Preconditions ---
  if (!fs.existsSync(META_PATH)) {
    console.log("No weekly-meta.json found — nothing to post. Exiting.");
    return;
  }
  const meta = JSON.parse(fs.readFileSync(META_PATH, "utf8"));

  if (meta.week_monday !== weekMonday) {
    console.log(
      `Meta is stale (week of ${meta.week_monday} vs current week of ${weekMonday}) — skipping.`
    );
    return;
  }

  const state = fs.existsSync(STATE_PATH)
    ? JSON.parse(fs.readFileSync(STATE_PATH, "utf8"))
    : { last_posted_week: null };
  if (state.last_posted_week === weekMonday) {
    console.log(`Already posted for the week of ${weekMonday} — skipping (re-run protection).`);
    return;
  }

  const captionPath = path.join(BLOG_DIR, meta.caption || "instagram-caption.txt");
  const caption = fs.existsSync(captionPath)
    ? fs.readFileSync(captionPath, "utf8").trim()
    : "";
  if (!caption) {
    throw new Error(`Caption file missing or empty: ${captionPath}`);
  }

  // weekly-hero.png keeps the same filename every week, so bust the
  // raw.githubusercontent CDN cache with a week-keyed query param — without
  // it, posting minutes after the push could serve LAST week's cached PNG
  // to Meta with no error anywhere.
  const heroUrl = `https://raw.githubusercontent.com/sanjmanak/show_lister/main/blog/${meta.hero || "weekly-hero.png"}?v=${weekMonday}`;

  console.log(`Week: ${meta.week_range} (Monday ${weekMonday})`);
  console.log(`Hero: ${heroUrl}`);
  console.log(`Caption: ${caption.length} chars`);

  // --- Token + Page ---
  await validateTokenAndGuards();
  const fbPageId = await resolveFacebookPageId();

  // --- Wait for the freshly pushed hero to be reachable ---
  console.log("\nVerifying hero image is publicly reachable…");
  await waitForImageUrl(heroUrl, 12, 10_000);

  const results = { igFeed: null, fbFeed: null, errors: [] };

  // --- Instagram Feed (anchor — must succeed) ---
  console.log("\n  IG FEED — Weekly Roundup");
  try {
    results.igFeed = await withTimeout(
      postIgFeedImage(heroUrl, caption),
      "IG Feed",
      CHANNEL_TIMEOUT_MS
    );
  } catch (err) {
    console.error(`\n  ERROR: IG Feed failed — ${err.message}`);
    // State NOT advanced — re-running the workflow retries this week, and
    // the email step still delivers the creative for a manual post.
    throw err;
  }

  // --- Facebook Feed (best-effort) ---
  if (fbPageId) {
    console.log("\n  FB FEED — Weekly Roundup");
    try {
      results.fbFeed = await withTimeout(
        postFbFeedPhoto(fbPageId, heroUrl, caption),
        "FB Feed",
        CHANNEL_TIMEOUT_MS
      );
    } catch (err) {
      console.error(`\n  WARNING: FB Feed failed — ${err.message}`);
      results.errors.push(`FB Feed: ${err.message}`);
    }
  } else {
    console.log("\n  FB FEED — Skipped (no Facebook Page ID resolved)");
  }

  // --- Advance state (anchor succeeded) ---
  state.last_posted_week = weekMonday;
  state.last_results = {
    igFeedMediaId: results.igFeed,
    fbFeedPostId: results.fbFeed,
    postedAt: new Date().toISOString(),
  };
  fs.writeFileSync(STATE_PATH, JSON.stringify(state, null, 2) + "\n");
  console.log(`\nState saved → ${STATE_PATH}`);

  console.log(`\n${"=".repeat(60)}`);
  console.log(`RESULTS — Weekly Roundup (week of ${weekMonday})`);
  console.log(`  IG Feed: ${results.igFeed ? "POSTED (ID: " + results.igFeed + ")" : "FAILED"}`);
  console.log(`  FB Feed: ${results.fbFeed ? "POSTED (ID: " + results.fbFeed + ")" : "SKIPPED/FAILED"}`);
  if (results.errors.length > 0) {
    results.errors.forEach((e) => console.log(`    - ${e}`));
  }
  console.log(`${"=".repeat(60)}`);
}

main()
  .then(() => shutdown(0))
  .catch((err) => {
    // Rate-limit: exit 0 so the workflow doesn't flag red. State was not
    // advanced — re-run the workflow to retry, or post manually from the
    // email that the workflow still sends.
    if (err && typeof err.message === "string" && err.message.startsWith("RATE_LIMITED")) {
      console.error(`\nRATE LIMITED — ${err.message}. Exiting 0; state not advanced.`);
      return shutdown(0);
    }
    console.error(`\nFATAL ERROR: ${err.message}`);
    if (err.stack) console.error(`\nStack trace:\n${err.stack}`);
    shutdown(1);
  });
